def solve_polyₘod(coeffs, m):
 # coeffs = [aₙ, ..., a₁, a₀]
 solutions = []
 for x in range(m):
 val = sum(c * (x ** (len(coeffs) - 1 - i)) for i, c in enumerate(coeffs))
 if val % m == 0:
 solutions.append(x)
 return solutions

# Solve x² + 1 ≡ 0 (mod 5)
print("Solutions to x² + 1 ≡ 0 (mod 5):", solve_polyₘod([1, 0, 1], 5)) # [2, 3]

def modᵢnverse_flt(a, p):
 # By FLT, a^(p-1) ≡ 1 (mod p) => a * a^(p-2) ≡ 1 (mod p)
 # Therefore inverse is a^(p-2) mod p
 return pow(a, p - 2, p)

print("Modular inverse of 3 mod 11:", modᵢnverse_flt(3, 11)) # 4 (since 3*4 = 12 ≡ 1 mod 11)

import numpy as np

def is_probability_vector(v):
 v = np.array(v)
 return np.all(v >= 0) and np.isclose(np.sum(v), 1.0)

print("[0.3, 0.5, 0.2] valid?", is_probability_vector([0.3, 0.5, 0.2])) # True
print("[0.4, 0.7, -0.1] valid?", is_probability_vector([0.4, 0.7, -0.1])) # False

